using Xunit;

public class U03_AlarmsTest
{
    private readonly Mock<IVtiService> _vtiServiceMock;
    private readonly Mock<IVteService> _vteServiceMock;
    private readonly Alarms _alarms;

    public U03_AlarmsTest()
    {
        _vtiServiceMock = new Mock<IVtiService>();
        _vteServiceMock = new Mock<IVteService>();
        _alarms = new Alarms(_vtiServiceMock.Object, _vteServiceMock.Object);
    }

    [Fact]
    public void LowVtiAlarm_AboveThreshold_Active()
    {
        _vtiServiceMock.Setup(s => s.CalculateVti()).Returns(1.2);
        _alarms.SetLowVtiThreshold(1.1);

        Assert.True(_alarms.IsLowVtiAlarmActive());
    }

    [Fact]
    public void LowVtiAlarm_BelowThreshold_Inactive()
    {
        _vtiServiceMock.Setup(s => s.CalculateVti()).Returns(0.9);
        _alarms.SetLowVtiThreshold(1.1);

        Assert.False(_alarms.IsLowVtiAlarmActive());
    }

    // ... similar tests for HighVtiAlarm, LowVteAlarm
}
